import { useEffect, useState } from "react";
import GuestRestriction from "../components/studio/GuestRestriction";
import LoadingState from "../components/LoadingState";
import ErrorState from "../components/ErrorState";
import { useAuth } from "../features/auth/AuthContext";
import { analysisApi } from "../services/analysis";
import { projectsApi, type Project } from "../services/projects";
import styles from "../features/studio/Studio.module.css";

/**
 * My Clips: clips live on their project (generated by Generate Clips
 * in the Studio or Find Clips on the project page, reviewed and
 * opened in the editor from there), so this page is a real index of
 * the user's projects with their actual candidate counts from the
 * API — every row links to the project's own clips view.
 */
export default function ClipsPage() {
  const { isGuest } = useAuth();
  const [projects, setProjects] = useState<Project[] | null>(null);
  const [clipCounts, setClipCounts] = useState<Record<string, number>>({});
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isGuest) return;
    let alive = true;
    projectsApi
      .listProjects({ pageSize: 50, sort: "newest" })
      .then(async ({ projects: loaded }) => {
        if (!alive) return;
        setProjects(loaded);
        const counts: Record<string, number> = {};
        await Promise.all(
          loaded.map(async (p) => {
            try {
              const { candidates } = await analysisApi.listCandidates(p.id);
              counts[p.id] = candidates.length;
            } catch {
              /* count stays unknown for this project; the row still links */
            }
          }),
        );
        if (alive) setClipCounts(counts);
      })
      .catch((err) => {
        if (alive) setError(err instanceof Error ? err.message : "Projects could not be loaded.");
      });
    return () => {
      alive = false;
    };
  }, [isGuest]);

  if (isGuest) return <GuestRestriction action="View your clips" />;
  if (error) return <ErrorState message={error} />;
  if (!projects) return <LoadingState message="Loading your projects…" />;

  return (
    <div className={styles.stack}>
      <section className={styles.panel}>
        <h3>My Clips — choose a project</h3>
        <p className={styles.panelIntro}>
          Clips are generated per project: paste a URL in the Studio and hit Generate Clips, or
          run Find Clips on a project. Each project&apos;s clips — with previews, scores and
          editor links — live on its project page.
        </p>
        {projects.length === 0 ? (
          <p className={styles.muted}>
            No projects yet. <a href="#/app/studio">Create one in the Studio</a> — paste a video
            URL, generate clips, and the project will be listed here.
          </p>
        ) : (
          <div className={styles.stack} style={{ gap: "var(--space-3)" }}>
            {projects.map((project) => (
              <div
                key={project.id}
                className={styles.buttonRow}
                style={{ justifyContent: "space-between" }}
              >
                <span>
                  <strong>{project.name}</strong>{" "}
                  <span className={styles.muted}>
                    ·{" "}
                    {clipCounts[project.id] === undefined
                      ? "clip count unavailable"
                      : `${clipCounts[project.id]} clip${clipCounts[project.id] === 1 ? "" : "s"}`}{" "}
                    · updated {new Date(project.updatedAt).toLocaleDateString()}
                  </span>
                </span>
                <a href={`#/app/projects/${project.id}`}>
                  <strong>View clips →</strong>
                </a>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
